name: 'Factory probe (sync tools)'
on:
  workflow_dispatch: {}
permissions:
  contents: read
  pull-requests: read
  actions: read
jobs:
  probe:
    runs-on: ubuntu-24.04
    timeout-minutes: 8
    steps:
      - name: Checkout factory (engine)
        uses: actions/checkout@v7
        with:
          repository: IstiN/dmtools-agents
          ref: ${{ github.sha }}
          path: factory-agents
          persist-credentials: false
      - name: Install dmtools CLI (pinned release bundle)
        env:
          DMTOOLS_VERSION: 'v0.1.16'
        run: |
          curl -fsSL "https://github.com/epam/dmtools-dart/releases/download/${DMTOOLS_VERSION}/install.sh" -o /tmp/i.sh
          bash /tmp/i.sh "${DMTOOLS_VERSION}"
          echo "$HOME/.dmtools/bin" >> "$GITHUB_PATH"
      - name: Probe github sync tools against fa
        env:
          SOURCE_GITHUB_TOKEN: ${{ secrets.SOURCE_GITHUB_TOKEN }}
        run: |
          cd factory-agents
          cat > js/probe_sync.js <<'JS'
          var out = {};
          try {
              var r1 = github_list_workflow_runs({
                  workspace: 'IstiN', repository: 'flutter_agent_harness',
                  workflowId: 'ci.yml', perPage: 5
              });
              var p1 = (typeof r1 === 'string') ? JSON.parse(r1) : r1;
              out.wfRuns = ((p1 && p1.workflow_runs) || []).length;
              out.wfRaw = JSON.stringify(p1).slice(0, 120);
          } catch (e) { out.wfErr = String((e && e.message) || e).slice(0, 120); }
          try {
              var r2 = github_list_workflow_runs({
                  workspace: 'IstiN', repository: 'flutter_agent_harness',
                  perPage: 5
              });
              var p2 = (typeof r2 === 'string') ? JSON.parse(r2) : r2;
              out.allRuns = ((p2 && p2.workflow_runs) || []).length;
          } catch (e) { out.allErr = String((e && e.message) || e).slice(0, 120); }
          try {
              var r3 = github_list_prs({
                  workspace: 'IstiN', repository: 'flutter_agent_harness',
                  state: 'open'
              });
              var p3 = (typeof r3 === 'string') ? JSON.parse(r3) : r3;
              var l3 = Array.isArray(p3) ? p3 : ((p3 && (p3.pullRequests || p3.data)) || []);
              out.prs = l3.length;
              out.prHead = (l3[0] && l3[0].head && l3[0].head.sha) ? 'sha-ok' : 'NO-HEAD';
          } catch (e) { out.prErr = String((e && e.message) || e).slice(0, 120); }
          console.log('PROBE_RESULT ' + JSON.stringify(out));
          JS
          cat > /tmp/probe.json <<'CFG'
          { "name": "JSRunner", "params": { "jsPath": "js/probe_sync.js", "jobParams": {} } }
          CFG
          dmtools run /tmp/probe.json 2>&1 | grep -E 'PROBE_RESULT|Error|error' | head -5

#!/usr/bin/env bash
# Output cache paths and keys for CI platforms.
#
# Usage:
#   cache.sh keys    tool1 tool2 ...   # export {TOOL}_CACHE_PATH + {TOOL}_CACHE_KEY
#   cache.sh restore tool1 tool2 ...   # same as 'keys' (actual restore done by CI YAML)
#   cache.sh save    tool1 tool2 ...   # print paths to cache (for CI YAML reference)
#   cache.sh info                      # print cache table for all known tools
#
# Examples:
#   cache.sh keys dmtools maestro copilot node playwright
#   cache.sh keys dmtools:v1.7.195 java:17
#
# After running, CI cache steps can reference exported env vars:
#   Bitrise:  key: $DMTOOLS_CACHE_KEY   paths: $DMTOOLS_CACHE_PATH
#   GHA:      key: ${{ env.DMTOOLS_CACHE_KEY }}   path: ${{ env.DMTOOLS_CACHE_PATH }}
set -eu

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "${SCRIPT_DIR}/_common.sh"

OS_TAG="$(uname -s | tr '[:upper:]' '[:lower:]')-$(uname -m)"

# ── Per-tool cache definitions ────────────────────────────────────────────────

_cache_dmtools() {
  local version="${1:-${DMTOOLS_VERSION:-v1.7.256}}"
  export_var "DMTOOLS_CACHE_PATH" "${HOME}/.dmtools"
  export_var "DMTOOLS_CACHE_KEY"  "dmtools-${version}-${OS_TAG}"
  # Restore key uses only the minor version prefix (e.g. v1.7.) so cache
  # hits are limited to the same minor line. The install script verifies
  # the exact version and reinstalls if the patch level differs.
  local minor_prefix="${version%.*}."
  export_var "DMTOOLS_CACHE_RESTORE_KEY" "dmtools-${minor_prefix}"
}

_cache_java() {
  local version="${1:-${JAVA_VERSION:-17}}"
  # Java is managed by the OS package manager; cache JAVA_HOME only
  local home=""
  if [ "$(detect_os)" = "macos" ]; then
    home="$(/usr/libexec/java_home -v "${version}" 2>/dev/null || echo "")"
  fi
  export_var "JAVA_CACHE_PATH" "${home:-/usr/lib/jvm}"
  export_var "JAVA_CACHE_KEY"  "java-${version}-${OS_TAG}"
}

_cache_node() {
  local version="${1:-${NODE_VERSION:-20}}"
  export_var "NODE_CACHE_PATH" "${HOME}/.nvm"
  export_var "NODE_CACHE_KEY"  "nvm-node${version}-${OS_TAG}"
}

_cache_maestro() {
