/**
 * Minimal workflow-file lint — trigger extraction + duplicate-key detection.
 *
 * Guards the gh-676 incident class: while .github/workflows/ai-teammate.yml
 * was unparseable (#669 merge residue — duplicate permission keys, fixed in
 * #671), GitHub kept a stale push-event registration, so every machine-sm
 * state-publish push to `factory-data` spawned an instant-fail event=push
 * run with zero jobs. Two invariants keep that class dead:
 *
 *   1. The AI Teammate stub declares EXACTLY its intended triggers
 *      (issues + workflow_dispatch — no push).
 *   2. No committed workflow contains duplicate mapping keys (YAML hard
 *      error → unparseable stretch → phantom registrations).
 *
 * This module is a deliberately small, dependency-free, indent-aware YAML
 * scanner — enough for workflow-shaped files, not a general YAML parser.
 * Pure functions only: no dmtools globals, safe to load anywhere.
 *
 * GraalJS constraints apply (var / plain functions, no Node APIs).
 */

// A mapping-key line: optional "- " list marker, a key, then a colon.
// The key may be quoted; '#', ':' cannot appear unquoted inside it.
var KEY_LINE_RE = /^(-[ \t]+)?("[^"]*"|'[^']*'|[^:#]+?)[ \t]*:([ \t].*)?$/;

// A block scalar introducer: value ends with | or > plus optional +/-/digit.
var BLOCK_SCALAR_RE = /^[|>][0-9]*[+-]?$/;

function indentOf(line) {
    var m = /^[ \t]*/.exec(line);
    return m ? m[0].length : 0;
}

function unquote(key) {
    if (key.length >= 2) {
        var q = key.charAt(0);
        if ((q === '"' || q === "'") && key.charAt(key.length - 1) === q) {
            return key.slice(1, -1);
        }
    }
    return key;
}

/**
 * Top-level event triggers of a workflow file: ['issues', 'workflow_dispatch'].
 * Handles the block form (on:\n  issues:) and the flow list form
 * (on: [push, ...]); nested trigger options (types, inputs, cron) never
 * leak into the result. Returns [] when the file has no on: block.
 */
function extractTriggers(text) {
    var lines = String(text).split(/\r?\n/);
    for (var i = 0; i < lines.length; i++) {
        var m = /^on:[ \t]*(.*)$/.exec(lines[i]);
        if (!m) {
            continue;
        }
        var inline = m[1].replace(/[ \t]+#.*$/, '').trim();
        if (inline === '') {
            // Block form: trigger names are the keys at the first indent
            // level under `on:`; dedent to column 0 ends the block.
            var triggers = [];
            var childIndent = -1;
            for (var j = i + 1; j < lines.length; j++) {
                var line = lines[j];
                if (line.trim() === '') {
                    continue;
                }
                var indent = indentOf(line);
                if (indent === 0) {
                    break;
                }
                var km = KEY_LINE_RE.exec(line.trim());
                if (!km) {
                    continue;
                }
                if (childIndent === -1) {
                    childIndent = indent;
                }
                if (indent === childIndent) {
                    triggers.push(unquote(km[2].trim()));
                }
            }
            return triggers;
        }
        if (inline.charAt(0) === '[') {
            var flow = inline.replace(/^\[[ \t]*/, '').replace(/[ \t]*\].*$/, '');
            var items = flow === '' ? [] : flow.split(',');
            var out = [];
            for (var k = 0; k < items.length; k++) {
                var item = items[k].replace(/[ \t]+#.*$/, '').trim();
                if (item !== '') {
                    out.push(unquote(item));
                }
            }
            return out;
        }
        return [inline]; // flow mapping form — report as one opaque entry
    }
    return [];
}

/**
 * Duplicate mapping keys within the same mapping, as [{key, line}] entries
 * (one per extra occurrence, `line` = 1-based line of the duplicate).
 * Tolerances that keep this a lint and not a false-positive machine:
 *   - list items start a fresh mapping (two steps may both use `name:`);
 *   - block-scalar content (run: |, run-name: >-) is never parsed as keys;
 *   - full-line comments and blank lines are ignored.
 */
function findDuplicateKeys(text) {
    var lines = String(text).split(/\r?\n/);
    // Frames of open mappings: { indent, keys }. A key at indent I pops
    // every frame with indent >= I, then records itself in the parent.
    var stack = [];
    var dups = [];
    var scalarIndent = -1; // >= 0 while inside a block scalar keyed at that indent

    for (var i = 0; i < lines.length; i++) {
        var raw = lines[i];
        if (raw.trim() === '') {
            continue; // blanks never end a block scalar
        }
        var indent = indentOf(raw);
        if (scalarIndent >= 0) {
            if (indent > scalarIndent) {
                continue; // scalar content — not YAML structure
            }
            scalarIndent = -1; // dedent ends the scalar
        }
        var content = raw.slice(indent);
        if (content.charAt(0) === '#') {
            continue;
        }
        if (content === '---' || content === '...') {
            stack = [];
            continue;
        }
        var m = KEY_LINE_RE.exec(content);
        if (!m) {
            continue; // scalar list entries like "- main" carry no keys
        }
        var isListItem = !!m[1];
        var key = unquote(m[2].trim());
        if (isListItem) {
            // Fresh mapping per item: pop the previous item's frame.
            // Frame indent I+1 sits between the "- " column and the
            // item's continuation keys at I+2.
            while (stack.length && stack[stack.length - 1].indent >= indent + 1) {
                stack.pop();
            }
            stack.push({ indent: indent + 1, keys: {} });
        } else {
            while (stack.length && stack[stack.length - 1].indent >= indent) {
                stack.pop();
            }
            if (stack.length) {
                var parent = stack[stack.length - 1];
                if (parent.keys[key]) {
                    dups.push({ key: key, line: i + 1 });
                } else {
                    parent.keys[key] = true;
                }
            }
            // Frame for this key's potential children.
            stack.push({ indent: indent, keys: {} });
        }
        // Block scalar: every deeper line belongs to the value.
        if (m[3] && BLOCK_SCALAR_RE.test(m[3].trim())) {
            scalarIndent = indent;
        }
    }
    return dups;
}

module.exports = {
    extractTriggers: extractTriggers,
    findDuplicateKeys: findDuplicateKeys
};

/*
 * Factory Board v2 — ALL deployment knobs live here.
 * Copy the folder, edit this file, host it. Nothing else to touch.
 *
 * Data: each factory's SM tick publishes a schema-2 state snapshot to its
 * repo's `factory-data` branch (jobParams.statePublish in machine-sm.yml):
 *   https://raw.githubusercontent.com/<O/R>/factory-data/data/<asset>.json
 * The board also renders schema 1 snapshots (the lane set before
 * 2026-10-01) — old history files never break it.
 */
window.FACTORY_BOARD_CONFIG = {
  // Refresh cadence (ms). The data itself is a tick snapshot (10 min cadence);
  // 60s polling just picks the new snapshot up promptly.
  refreshMs: 60000,

  // A snapshot older than this announces itself as STALE (gh-769: a stalled
  // SM tick used to leave lanes that contradicted the live repo — now the
  // board says so instead of silently rendering old state).
  staleAfterMs: 1800000,

  // Branding (the logo is an inline SVG in index.html — no emoji anywhere)
  title: 'Factory Board',

  // One entry per factory. stateUrl = the factory-data branch CDN link the
  // SM tick publishes (public, token-free, no rate limits).
  //   asset name = cfg.statePublish.asset of that factory
  //   accent     = CSS color for the tab + lane highlights (style knob)
  //   repo is NOT needed here — the snapshot itself carries st.repo and the
  //   board links cards against it (schema 1 bug: links went to
  //   github.com/undefined/pull/N when repo was read from this config).
  factories: [
    {
      id: 'fa',
      name: 'flutter_agent_harness',
      stateUrl: 'https://raw.githubusercontent.com/IstiN/flutter_agent_harness/factory-data/data/fa-state.json',
      accent: '#22d3ee'
    },
    {
      id: 'dart',
      name: 'dmtools-dart',
      stateUrl: 'https://raw.githubusercontent.com/epam/dmtools-dart/factory-data/data/dart-state.json',
      accent: '#34d399'
    },
    {
      id: 'agents',
      name: 'dmtools-agents',
      stateUrl: 'https://raw.githubusercontent.com/IstiN/dmtools-agents/factory-data/data/agents-state.json',
      accent: '#a78bfa'
    }
  ],

  // Lane rendering order + titles — the PIPELINE order (schema 2). A card
  // moves left→right exactly once per stage. Schema 1 snapshots map onto it:
  // `fresh` renders as `pr_created`; development/merged_recent stay empty.
  // pr_validation (gh-716) holds PRs whose head validation run is still
  // in flight — the window between "PR created" and "reviewed".
  lanes: [
    { id: 'development',    title: 'Development',          icon: 'dev' },
    { id: 'pr_created',     title: 'PR created',           icon: 'pr' },
    { id: 'pr_validation',  title: 'PR validation',        icon: 'validate' },
    { id: 'review',         title: 'Review',               icon: 'review' },
    { id: 'approved_queue', title: 'Approved queue · FIFO', icon: 'queue' },
    { id: 'validating',     title: 'Validating · mutex',   icon: 'validate' },
    { id: 'merged_recent',  title: 'Merged · 24h',         icon: 'merged' }
  ],

  // v3: backlog columns — open issues from the same snapshot's `backlog`
  // section (bucket ids come from factoryState.js backlogBucket). Order is
  // the flow: assigned → queued → owner-held → unsorted inbox.
  backlogColumns: [
    { id: 'in_dev',  title: 'In dev · assigned',     icon: 'dev' },
    { id: 'queued',  title: 'agent:dev queued',      icon: 'queue' },
    { id: 'blocked', title: 'Blocked · owner hold',  icon: 'blocked' },
    { id: 'inbox',   title: 'Inbox',                 icon: 'inbox' }
  ],

  // Labels highlighted as badges on cards (the rest stay subtle)
  badgeLabels: ['pr_approved', 'ai_validated', 'ai_pr_reviewed', 'ai_validating',
                'dependencies', 'agent:dev', 'agent:review', 'agent:rework',
                'github_actions'],

  // Repo link base for PR/issue links (n = number; kind = 'pull'|'issues')
  prUrl: function (repo, n, kind) {
    return 'https://github.com/' + repo + '/' + (kind || 'pull') + '/' + n;
  }
};

