        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({
            setupCommands: [{ name: 'no-op' }, '']
        }, './dependencies/repo');

        assert.equal(result.ran, 0);
        assert.deepEqual(loaded.commands, []);
