/**
 * Unit tests for js/common/setupCommands.js
 */

function loadSetupCommands(mocks) {
    var commands = [];
    var mod = loadModule(
        'js/common/setupCommands.js',
        null,
        Object.assign({
            cli_execute_command: function(args) {
                commands.push(args);
                return 'ok';
            }
        }, mocks || {})
    );
    return { mod: mod, commands: commands };
}

suite('setupCommands helper', function() {

    test('does nothing when customParams.setupCommands is absent', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({}, './dependencies/repo');

        assert.equal(result.ran, 0);
        assert.deepEqual(loaded.commands, []);
    });

    test('does nothing when customParams.setupCommands is not an array', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({ setupCommands: 'not-an-array' }, './dependencies/repo');

        assert.equal(result.ran, 0);
        assert.deepEqual(loaded.commands, []);
    });

    test('runs plain string commands in the default working directory', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({
            setupCommands: ['bash agents/setup/java.sh 25', 'bash agents/setup/maven.sh 3.9.9']
        }, './dependencies/example-repo');

        assert.equal(result.ran, 2);
        assert.equal(loaded.commands.length, 2);
        assert.equal(loaded.commands[0].command, 'bash agents/setup/java.sh 25');
        assert.equal(loaded.commands[0].workingDirectory, './dependencies/example-repo');
        assert.equal(loaded.commands[1].workingDirectory, './dependencies/example-repo');
        assert.equal(result.results[0].success, true);
    });

    test('object entries can override workingDir and name', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({
            setupCommands: [
                { name: 'install-java', command: 'bash agents/setup/java.sh 25' },
                { name: 'custom-dir', command: 'ls', workingDir: '/tmp/other' }
            ]
        }, './dependencies/example-repo');

        assert.equal(loaded.commands[0].workingDirectory, './dependencies/example-repo', 'falls back to default working dir');
        assert.equal(loaded.commands[1].workingDirectory, '/tmp/other', 'entry-level workingDir overrides default');
        assert.equal(result.results[0].name, 'install-java');
        assert.equal(result.results[1].name, 'custom-dir');
    });

    test('plain string command failures are non-fatal and recorded', function() {
        var loaded = loadSetupCommands({
            cli_execute_command: function() { throw new Error('boom'); }
        });

        var result = loaded.mod.runSetupCommands({
            setupCommands: ['some-flaky-warmup-command']
        }, './dependencies/repo');

        assert.equal(result.ran, 1);
        assert.equal(result.results[0].success, false);
        assert.equal(result.results[0].error, 'boom');
    });

    test('allowFailure: false makes a failing command throw and stop the loop', function() {
        var calls = [];
        var loaded = loadSetupCommands({
            cli_execute_command: function(args) {
                calls.push(args.command);
                if (args.command === 'check-required-creds') {
                    throw new Error('REQUIRED_TOKEN not set');
                }
                return 'ok';
            }
        });

        var threw = false;
        try {
            loaded.mod.runSetupCommands({
                setupCommands: [
                    { name: 'required-check', command: 'check-required-creds', allowFailure: false },
                    { name: 'should-not-run', command: 'never-called' }
                ]
            }, './dependencies/repo');
        } catch (e) {
            threw = true;
            assert.ok(e.message.indexOf('required-check') !== -1, 'error should mention the failing step name');
            assert.ok(e.message.indexOf('REQUIRED_TOKEN not set') !== -1, 'error should include the underlying failure');
        }

        assert.equal(threw, true, 'should throw when a required setup command fails');
        assert.deepEqual(calls, ['check-required-creds'], 'must stop after the required command fails');
    });

    test('console output of a failing setup command is bounded (dm.ai#635 log-processor stall)', function() {
        // A multi-megabyte failure printed as ONE console line stalls the GitHub Actions
        // log processor (~400 s per 500 KB line), turning a 13 s suite into a 13 min step.
        var warned = [];
        var realWarn = console.warn;
        console.warn = function() { warned.push(Array.prototype.slice.call(arguments).join(' ')); };
        try {
            var loaded = loadSetupCommands({
                cli_execute_command: function() { throw new Error('Z'.repeat(500000)); }
            });
            var result = loaded.mod.runSetupCommands({
                setupCommands: [{ name: 'huge', command: 'mvn clean verify' }]
            }, './dependencies/repo');
            assert.equal(result.results[0].success, false);
            assert.equal(result.results[0].error.length, 500000, 'the full text stays in the result for callers');
        } finally {
            console.warn = realWarn;
        }
        assert.ok(warned.length >= 1, 'the failure must still be logged');
        warned.forEach(function(line) {
            assert.ok(line.length < 10000, 'logged line must be bounded, got ' + line.length + ' chars');
        });
    });

    test('skips entries without a command', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCommands({
            setupCommands: [{ name: 'no-op' }, '']
        }, './dependencies/repo');

        assert.equal(result.ran, 0);
        assert.deepEqual(loaded.commands, []);
    });

    test('required setup command failure with huge output is truncated in the thrown message', function() {
        // Regression test: a required setup command (e.g. `mvn clean verify`) can fail
        // with megabytes of console output embedded in the error message. That message
        // is later posted verbatim as a Jira/tracker comment by callers of
        // runSetupCommands (preCliDevelopmentSetup.js, preCliReworkSetup.js); trackers
        // reject oversized comments (e.g. Jira's ~350000 char limit), and previously
        // that posting failure was silently swallowed — leaving the ticket with zero
        // visibility into why setup failed. The thrown error must stay bounded.
        var hugeOutput = 'X'.repeat(500000);
        var loaded = loadSetupCommands({
            cli_execute_command: function() { throw new Error(hugeOutput); }
        });

        var threw = false;
        try {
            loaded.mod.runSetupCommands({
                setupCommands: [
                    { name: 'build-test-database-image', command: 'mvn clean verify', allowFailure: false }
                ]
            }, './dependencies/repo');
        } catch (e) {
            threw = true;
            assert.ok(e.message.length < 10000, 'thrown message must be bounded, got ' + e.message.length + ' chars');
            assert.ok(e.message.indexOf('build-test-database-image') !== -1, 'error should mention the failing step name');
            assert.ok(e.message.indexOf('truncated') !== -1, 'truncated message should say so');
        }

        assert.equal(threw, true, 'should throw when a required setup command fails');
    });

    test('short error messages pass through truncateSetupError unchanged', function() {
        var loaded = loadSetupCommands();
        assert.equal(loaded.mod.truncateSetupError('short message'), 'short message');
        assert.equal(loaded.mod.truncateSetupError(undefined), undefined);
    });
});

suite('setupCommands buildSetupWarningsMarkdown', function() {

    test('returns null when there are no failures', function() {
        var loaded = loadSetupCommands();
        var result = loaded.mod.runSetupCom…

/**
 * Runs project-specific prerequisite/setup commands before the CLI agent starts.
 *
 * Configured via customParams.setupCommands: an array of either plain command
 * strings or objects { command, name, workingDir, allowFailure }.
 *
 * - Plain strings and entries without `allowFailure: false` are non-fatal:
 *   a failure is logged and the loop continues (useful for warm-up/caching
 *   steps that shouldn't block the whole pipeline).
 * - `allowFailure: false` makes the step required: a failure throws, stopping
 *   development before the CLI agent runs (useful for prerequisite checks
 *   like "required credentials are present").
 *
 * Used by: preCliDevelopmentSetup.js (story_development), preCliReworkSetup.js
 * (pr_rework) — runs once per ticket, right after the git branch is checked
 * out and before the CLI coding agent starts.
 *
 * ⚠️ IMPORTANT — every command here goes through cli_execute_command, which:
 * 1. Only allows executables in the whitelist: git, gh, dmtools, npm, yarn,
 *    docker, kubectl, terraform, ansible, aws, gcloud, az (base list). Anything
 *    else (bash, mvn, gradle, test, python3, ...) MUST be added via
 *    params.envVariables.CLI_ALLOWED_COMMANDS (comma-separated) on the agent
 *    JSON, e.g. { "envVariables": { "CLI_ALLOWED_COMMANDS": "bash,mvn" } }.
 * 2. Rejects any command string containing shell metacharacters —
 *    `;`, `&&`, `||`, `|`, `>`, `<`, `` ` ``, `$(...)`, `${...}` — even if the
 *    leading executable is whitelisted. There is NO way to pass a compound
 *    command (e.g. "test -n \"$X\" && echo ok") directly.
 *    If you need conditional/compound logic, put it inside a checked-in .sh
 *    script file and invoke that file with a single simple command
 *    (e.g. "bash agents/scripts/check_required_env_vars.sh VAR1 VAR2") — the
 *    metacharacter check only inspects the command string passed to
 *    cli_execute_command, not the contents of a script it runs.
 */

// Required setup command failures embed the raw tool output (e.g. full `mvn`/`gradle`
// console output, which can run into megabytes) in the thrown Error's message. Callers
// (preCliDevelopmentSetup.js, preCliReworkSetup.js) post that message straight into a
// Jira/tracker comment; trackers reject oversized comments (e.g. Jira's ~350000 char
// limit) and the resulting post failure can end up silently swallowed, leaving the
// ticket with zero visibility into why setup failed. Cap the embedded output here, at
// the source, so every consumer of this error automatically gets a bounded message.
var MAX_SETUP_ERROR_CHARS = 8000;

function truncateSetupError(text) {
    if (typeof text !== 'string' || text.length <= MAX_SETUP_ERROR_CHARS) {
        return text;
    }
    // Keep the head (command/context) and tail (usually the actual failure/exception)
    // since Maven/Gradle failures are typically reported at the very end of the output.
    var headLen = Math.floor(MAX_SETUP_ERROR_CHARS * 0.4);
    var tailLen = MAX_SETUP_ERROR_CHARS - headLen;
    var omitted = text.length - headLen - tailLen;
    return text.slice(0, headLen) +
        '\n... [truncated ' + omitted + ' char(s) — see CLI logs for full output] ...\n' +
        text.slice(text.length - tailLen);
}

function runSetupCommands(customParams, defaultWorkingDir) {
    var commands = (customParams && customParams.setupCommands) || [];
    if (!Array.isArray(commands) || commands.length === 0) {
        return { ran: 0, results: [] };
    }

    var results = [];
    for (var i = 0; i < commands.length; i++) {
        var entry = commands[i];
        var isString = typeof entry === 'string';
        var command = isString ? entry : (entry && entry.command);
        if (!command) continue;

        var workingDir = (!isString && entry.workingDir) || defaultWorkingDir || null;
        var allowFailure = isString ? true : (entry.allowFailure !== false);
        var name = (!isString && entry.name) || command;

        try {
            console.log('Running setup command "' + name + '": ' + command);
            var args = { command: command };
            if (workingDir) args.workingDirectory = workingDir;
            var output = cli_execute_command(args);
            results.push({ name: name, success: true, output: output });
        } catch (e) {
            var errorText = e && e.message ? e.message : String(e);
            // Log the BOUNDED text only. The full errorText stays in `results` (callers and
            // buildSetupWarningsMarkdown apply their own bound). A multi-megabyte tool output
            // printed as a single console line makes the GitHub Actions log processor take
            // minutes (dm.ai#635: two 500 KB lines = ~800 s of a 13 s test run).
            console.warn('Setup command "' + name + '" failed:', truncateSetupError(errorText));
            results.push({ name: name, success: false, error: errorText });
            if (allowFailure === false) {
                throw new Error('Required setup command failed: ' + name + ' — ' + truncateSetupError(errorText));
            }
        }
    }
    return { ran: results.length, results: results };
}

/**
 * Builds a markdown summary of any non-fatal ("allowFailure" — the default) setup
 * command failures from a runSetupCommands() result, or null if none failed.
 *
 * Non-fatal failures are, by design, only logged to the CI console (see
 * runSetupCommands() above) — the CLI coding agent never sees them unless the caller
 * writes this out to an input file. Without that, a step like "build the project's
 * Docker test image" can fail for a genuine, agent-fixable content reason (e.g. a bad
 * migration file) and the agent will start working on the ticket with zero awareness
 * that anything is wrong, only to hit a confusing downstream failure later (or worse,
 * silently ship a broken fix). Callers should write this to e.g. `setup_warnings.md` in
 * the input folder whenever it returns non-null, so the CLI agent can read it as context
 * and attempt a fix, the same way it already does for merge_conflicts.md.
 */
function buildSetupWarningsMarkdown(runResult) {
    var results = (runResult && runResult.results) || [];
    var failures = results.filter(function(r) { return r && r.success === false; });
    if (failures.length === 0) {
        return null;
    }
    var lines = [
        '# Setup Command Warnings',
        '',
        'The following setup command(s) failed but were configured as non-fatal ' +
            '(allowFailure is not set to false), so environment setup continued. ' +
            'If this failure is caused by a fixable issue in the code (e.g. a bad ' +
            'migration, a broken test, a compile error), please investigate and fix it ' +
            'as part of this task.',
        ''
    ];
    for (var i = 0; i < failures.length; i++) {
        lines.push('## ' + failures[i].name);
        lines.push('');
        lines.push('```');
        lines.push(truncateSetupError(failures[i].error || ''));
        lines.push('```');
        lines.push('');
    }
    return lines.join('\n');
}

module.exports = {
    runSetupCommands: runSetupCommands,
    truncateSetupError: truncateSetupError,
    buildSetupWarningsMarkdown: buildSetupWarningsMarkdown
};

/**
 * Pre-CLI Rework Setup Action (preCliJSAction for pr_rework agent)
 * 1. Finds the existing PR for the ticket
 * 2. Checks out the PR branch
 * 3. Merges origin/{baseBranch} into the PR branch (auto-update, before setup commands run —
 *    see the comment above the detectMergeConflicts() call for why the order matters)
 * 4. Runs project-specific setup commands (build/verify) against the now-updated branch
 * 5. Writes input folder: pr_info.md, pr_diff.txt, pr_discussions.md, pr_discussions_raw.json
 *    plus the pinned gh-799 input contract: pr_discussions_raw.json (even with 0 threads),
 *    ci_failures.md (even with 0 failed checks) and review_state.md (review verdicts +
 *    decision state) — the complete open-item picture regardless of which armer fired.
 * 6. Fetches question subtasks with answers (extra context)
 * 7. Posts "Rework Started" comment to the ticket (Jira/ADO/GitHub via common/trackers.js),
 *    rendered in the ticket's markup flavor (Markdown on GitHub, wiki on Jira — gh-770)
 */

var configLoader = require('./configLoader.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const { resolveStatuses } = require('./config.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var restoreFromReleases = require('./restoreFromReleases.js');
var setupCommands = require('./common/setupCommands.js');
var baseBranchMarker = require('./common/baseBranchMarker.js');

/**
 * Optionally syncs the PR's base branch with its own upstream (config.git.baseBranch)
 * before merge-conflict detection runs. Relevant in two-branch mode, where the PR's base is
 * a long-lived branch (e.g. "release/rc_*") that can drift stale relative to
 * config.git.baseBranch over time. Delegates to a project-specific hook
 * (customParams.branchSyncFnPath) because syncing may require bypassing branch-protection
 * rules that block direct pushes to that branch — same rationale as
 * customParams.branchCreateFnPath in checkoutBranch.js.
 *
 * No-op when branchSyncFnPath isn't configured, or when the PR's base already IS
 * config.git.baseBranch (nothing to sync). Failures are logged and swallowed — the sync is
 * a best-effort freshness step, not a hard prerequisite for the rest of the rework flow.
 *
 * @param {string} baseBranch    - the PR's base branch (prDetails.base.ref)
 * @param {Object} customParams  - agent customParams (may contain branchSyncFnPath)
 * @param {Object} config        - resolved project config (config.git.baseBranch, workingDir)
 */
function syncBaseBranchIfConfigured(baseBranch, customParams, config) {
    if (!customParams || !customParams.branchSyncFnPath || !baseBranch || baseBranch === config.git.baseBranch) {
        return;
    }
    var branchSyncFn = configLoader.loadHookFn(customParams.branchSyncFnPath, 'branchSyncFnPath');
    if (!branchSyncFn) {
        return;
    }
    try {
