{"content":"suite('probe', function () {
    test('fixture transport', function () {
        var shq = function (v) { return "'" + String(v).replace(/'/g, "'\\''") + "'"; };
        var content = 'name: Quality\n      - uses: dart-lang/setup-dart@v1\n        with:\n          channel: beta';
        var lines = [
            'r="$(pwd)"',
            'd="$(mktemp -d)"',
            'mkdir -p "$d/.github/workflows"',
            'printf %s ' + shq(content) + " > '$d/.github/workflows/quality.yml'",
            'wc -c "$d/.github/workflows/quality.yml"',
            'cat "$d/.github/workflows/quality.yml"',
            'rc=$?; cd /; rm -rf "$d"; exit $rc'
        ];
        var out = cli_execute_command({ command: 'bash -c ' + shq(lines.join('\n')) });
        console.log('RAW_OUT>>>' + String(out) + '<<<');
        assert.ok(true);
    });
});
","path":"js/unit-tests/test_probe_tmp.js"}

